using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .Build();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(ResearchTools.SearchWeb),
    AIFunctionFactory.Create(ResearchTools.SaveNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic, you:
        1. Search the web for relevant information using multiple queries.
        2. Save important findings as notes using the note-taking tool.
        3. After gathering enough information, retrieve all your notes and
           produce a concise, well-structured summary with key points.
        Always cite your sources. Use at least 2 different search queries
        to get a well-rounded view of the topic.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics via web search and summarizes findings.",
    tools: tools);

Console.WriteLine("Research Agent ready. Type a topic to research (or 'quit' to exit).");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    ResearchTools.ClearNotes();

    Console.WriteLine($"\nResearching: {topic}\n");

    var session = await agent.CreateSessionAsync();
    var response = await agent.RunAsync(
        $"Research the following topic and provide a summary: {topic}",
        session,
        new ChatClientAgentRunOptions(new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        }));

    Console.WriteLine(response.Text);
}

/// <summary>Tools available to the research agent.</summary>
static class ResearchTools
{
    private static readonly List<string> s_notes = [];
    private static readonly HttpClient s_http = new();

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🔍 Searching: {query}");

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "ResearchAgent/1.0 (compatible; research bot)");

            var response = await s_http.SendAsync(request);
            var html = await response.Content.ReadAsStringAsync();

            var snippets = ExtractSnippets(html, query);

            if (snippets.Count == 0)
                return $"No results found for '{query}'.";

            return JsonSerializer.Serialize(new { query, results = snippets });
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record important findings.")]
    public static string SaveNote(
        [Description("The note content to save")] string content,
        [Description("Source URL or description")] string source)
    {
        var note = $"[{s_notes.Count + 1}] {content} (Source: {source})";
        s_notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({s_notes.Count} total)");
        return $"Note saved successfully. You now have {s_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", s_notes);
